-- Mission Giver
lang["#MISSION_GIVER_LOGAN"] = "Lieutenant Logan"
lang["#MISSION_GIVER_LOGAN_SUBTITLE"] = "New California Republic"
lang["#MISSION_GIVER_LOGAN_NEW"] = "New around here? Talk to Major Redman and help around town before coming back to me. Then we can talk about work. I need someone who can prove themself loyal to the republic."
lang["#MISSION_GIVER_LOGAN_GREET_N100"] = "Get out of my sight."
lang["#MISSION_GIVER_LOGAN_GREET_800"] = "$playername, I have more jobs for you to do. Continue proving yourself to the republic."
lang["#MISSION_GIVER_LOGAN_GREET_1000"] = "$playername, welcome back. I have the perfect job for someone loyal to the republic like you."
lang["#MISSION_GIVER_LOGAN_GREET_FINISHED"] = "$playername, it's an honor to see you. However, I have nothing more for you to do. You are a hero to the republic."

-- Missions
lang["#MISSION_LOGAN_LINEINTHESANDPT1"] = "Line in the Sand: Eighties Tribe"
lang["#MISSION_LOGAN_LINEINTHESANDPT1_DESC"] = "$playername, I have several tasks that require someone who is undoubtedly trustworthy. If you are interested, you can start by proving yourself by eradicating the nearby bandits."
lang["#MISSION_LOGAN_LINEINTHESANDPT1_HINT"] = "**WARNING** Completing this quest will irreversibly damage your reputation with the Eighties."
lang["#MISSION_LOGAN_LINEINTHESANDPT1_COMPLETE"] = "Great job $playername! The area surrounding the town will be much safer thanks to you."

lang["#MISSION_LOGAN_GEARREQUISITION"] = "Gear Requisition"
lang["#MISSION_LOGAN_GEARREQUISITION_DESC"] = "Hello $playername, after your recent contribution I have put in a request for you to receive an official set of armor. I just need a few things from you and it's all yours. "
lang["#MISSION_LOGAN_GEARREQUISITION_HINT"] = "Obtain the required crafting materials and vouchers. Most of these items can be obtained from fighting enemies or scavenging. Some merchants may stock required items."
lang["#MISSION_LOGAN_GEARREQUISITION_COMPLETE"] = "Congratulations $playername, I hope you continue your great work."

lang["#MISSION_LOGAN_LINEINTHESANDPT2"] = "Line in the Sand: Rockbiters"
lang["#MISSION_LOGAN_LINEINTHESANDPT2_DESC"] = "$playername, after your triumph against the Eighties, I have a harder task. There's a bandit group near the Desert Rangers in Yolla Bolly. They cannot be allowed to prosper, go to Yolla Bolly and eliminate them."
lang["#MISSION_LOGAN_LINEINTHESANDPT2_HINT"] = "**WARNING** Completing this quest will irreversibly damage your reputation with the Rockbiters."
lang["#MISSION_LOGAN_LINEINTHESANDPT2_COMPLETE"] = "The Desert Rangers and Valley Survivalists will greatly appreciate your work, as do I. I have one last problematic group that must be addressed before I give you the truly important tasks."

lang["#MISSION_LOGAN_LINEINTHESANDPT3"] = "Line in the Sand: Cipher Company"
lang["#MISSION_LOGAN_LINEINTHESANDPT3_DESC"] = "Cipher Company has long been a thorn in our side, peddling drugs and evading taxes. Not to mention they are in direct armed conflict with our allies. $playername, go and cripple their organization on Mountain Pass."
lang["#MISSION_LOGAN_LINEINTHESANDPT3_HINT"] = "**WARNING** Completing this quest will irreversibly damage your reputation with Cipher Company."
lang["#MISSION_LOGAN_LINEINTHESANDPT3_COMPLETE"] = "Mountain Pass will be far less dangerous to traverse with Cipher Company's operations damaged."

lang["#MISSION_LOGAN_REGIONPROTECTION"] = "Region Protection"
lang["#MISSION_LOGAN_REGIONPROTECTION_DESC"] = "You've worked hard to protect the surrounding region from threats, don't squander it by letting those threats rebuild $playername."
lang["#MISSION_LOGAN_REGIONPROTECTION_HINT"] = "Eliminate 1 boss and 10 members from the Eighties, Rockbiters, and Cipher Company."
lang["#MISSION_LOGAN_REGIONPROTECTION_COMPLETE"] = "Amazing work keeping the region safe, here's your reward."

lang["#MISSION_LOGAN_OURBESTFRIENDS"] = "Our Best Friends"
lang["#MISSION_LOGAN_OURBESTFRIENDS_DESC"] = "Now that you've proven yourself, we can finally talk about real important business. Expedition into the northern regions have proven quite difficult, however the Desert Rangers have made safehouses around. Collect reports from them to gather a real assessment of the surrounding regions."
lang["#MISSION_LOGAN_OURBESTFRIENDS_HINT"] = "Collect the status report from the Desert Rangers headquarters in Yolla Bolly."
lang["#MISSION_LOGAN_OURBESTFRIENDS_COMPLETE"] = "Even with your prior contributions, the situation isn't looking good. Good work fetching these reports."
lang["#MISSION_LOGAN_OURBESTFRIENDS_ITEMNAME"] = "Regions Status Report"

lang["#MISSION_LOGAN_RANGERSOLIDARITY"] = "Solidarity with the Rangers"
lang["#MISSION_LOGAN_RANGERSOLIDARITY_DESC"] = "The reports show that even in Yolla Bolly, things are dire. We need you to go help the Desert Rangers stabalize the region first."
lang["#MISSION_LOGAN_RANGERSOLIDARITY_HINT"] = "Eliminate these enemies in Yolla Bolly. Deathclaws can be found nearby and at the temple. Protectrons can be found in the factory and in the silo. Rockbiters can be found in the mines and in the tunnel."
lang["#MISSION_LOGAN_RANGERSOLIDARITY_COMPLETE"] = "Yolla Bolly may finally start becoming a safer place thanks to you. With the southern regions stabilized, it's time to start looking north."

lang["#MISSION_LOGAN_RANGEROUTPOSTSUPPORT"] = "Ranger Safehouse Support"
lang["#MISSION_LOGAN_RANGEROUTPOSTSUPPORT_DESC"] = "The Desert Ranger safehouse in Ash Lands has sent reports back of a large mutant army in the region. We need to thin those numbers down."
lang["#MISSION_LOGAN_RANGEROUTPOSTSUPPORT_HINT"] = "Eliminate 100 Super Mutants in Ash Lands."
lang["#MISSION_LOGAN_RANGEROUTPOSTSUPPORT_COMPLETE"] = "Great job dealing with those mutants, however reports show that the region is still extremely hostile. I have another job for you."

lang["#MISSION_LOGAN_CAMPWILLOWSUPPORT"] = "Helping Camp Willow"
lang["#MISSION_LOGAN_CAMPWILLOWSUPPORT_DESC"] = "Camp Willow in Mountain Pass is under constant threat from an ever-growing canninbal bandit group. They need to be stopped or else all paths to the northern regions will be blocked."
lang["#MISSION_LOGAN_CAMPWILLOWSUPPORT_HINT"] = "Find and eliminate 100 Ice Pick bandits in Mountain Pass."
lang["#MISSION_LOGAN_CAMPWILLOWSUPPORT_COMPLETE"] = "Thanks to your hard work $playername, the pass will remain open. Although, danger still lurks around every corner." 

lang["#MISSION_LOGAN_PACIFYCOOLSNOW"] = "Region Pacification: Mountain Pass"
lang["#MISSION_LOGAN_PACIFYCOOLSNOW_DESC"] = "There's more threats in Mountain Pass than just the Ice Picks, the wildlife alongside Cipher Company are great threats to the stability of the region."
lang["#MISSION_LOGAN_PACIFYCOOLSNOW_HINT"] = "Find and eliminate the yao guai, mirelurk, and Cipher bosses in Monutain Pass."
lang["#MISSION_LOGAN_PACIFYCOOLSNOW_COMPLETE"] = "With the major threats of the region gone, Camp Willow will prosper. However, we must remain vigilant as they may quickly come back."

lang["#MISSION_LOGAN_PACIFYAPOC"] = "Region Pacification: Ashlands"
lang["#MISSION_LOGAN_PACIFYAPOC_DESC"] = "We're going to get nowhere if we spend all our time and resources attacking the grunts, we need to go after the bosses of Ash Lands region."
lang["#MISSION_LOGAN_PACIFYAPOC_HINT"] = "Find and eliminate all of the bosses in Ash Lands."
lang["#MISSION_LOGAN_PACIFYAPOC_COMPLETE"] = "With the bosses of the region dead, perhaps the rangers at the safehouse can breathe a sigh of relief. Although, that region remains inhospitable and dangerous."

lang["#MISSION_LOGAN_PACIFYKNEEDEEP"] = "Region Pacification: Dead Estuary"
lang["#MISSION_LOGAN_PACIFYKNEEDEEP_DESC"] = "According to the reports, there's a region in the north that contains valuable natural resources and materials, along with pre-war installations. However, it's home to dangerous wildlife and smugglers. Clear out the region so that it can be used."
lang["#MISSION_LOGAN_PACIFYKNEEDEEP_HINT"] = "Find and eliminate anglers, mirelurks, gatorclaws, smugglers, and the boss in Dead Estuary."
lang["#MISSION_LOGAN_PACIFYKNEEDEEP_COMPLETE"] = "Now that the region is enterable, the resources will now be available to us. Great work as always $playername."

lang["#MISSION_LOGAN_PACIFYSALEM"] = "Region Pacification: Salem"
lang["#MISSION_LOGAN_PACIFYSALEM_DESC"] = "From the reports, there claims to be an deciminated urban region that contains refugees surrounded by a power struggle for the region. Help solve this struggle by eliminating the bandits and mutant forces."
lang["#MISSION_LOGAN_PACIFYSALEM_HINT"] = "Find and eliminate Shadowed and Unity in Salem."
lang["#MISSION_LOGAN_PACIFYSALEM_COMPLETE"] = "Now that the two of the groups in Salem have taken large losses, the refugees should be able to find some stability."

lang["#MISSION_LOGAN_WINFORTHEBEAR"] = "Another Win for the Bear"
lang["#MISSION_LOGAN_WINFORTHEBEAR_DESC"] = "With all your contributions, I have a once in a lifetime opportunity. A pre-war riot shotgun, all I need from you a is a few materials and it's all yours."
lang["#MISSION_LOGAN_WINFORTHEBEAR_HINT"] = "Advanced materials can rarely be found throughout the wasteland. Some riot shotgun attachments will be purchaseable after completing this quest."
lang["#MISSION_LOGAN_WINFORTHEBEAR_COMPLETE"] = "$playername, I have nothing more left for you. If I could give you a medal I would. You single-handedly protected Salt Wells and its surrounding regions."

lang["#MISSION_LOGAN_RIOTSUPPRESSION"] = "Riot Suppression"
lang["#MISSION_LOGAN_RIOTSUPPRESSION_DESC"] = "Interested in a victory lap? How about you try out that riot shotgun."
lang["#MISSION_LOGAN_RIOTSUPPRESSION_HINT"] = "Find and eliminate any 300 enemies using a Riot Shotgun."
lang["#MISSION_LOGAN_RIOTSUPPRESSION_COMPLETE"] = "As expected from you $playername, flawless as always."

RELOADSCHEMA = true